(() => {
  let lang='fi', mode=0, state;
  const t=(fi,en)=>lang==='fi'?fi:en;
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const button=(id,fi,en,cls='')=>`<button data-action="${id}" class="${cls}">${t(fi,en)}</button>`;
  function reset(n){mode=n;state={person:true,busy:false,warning:false,tray:false,idle:false,request:false,remote:false,value:'',draft:'',message:''};return view();}
  function view(){return `<section class="sb" data-mode="${mode}" data-owner="${state.person?'person':'agent'}">
    <div class="directions"><p class="${mode===0?'selected':''}">${t('1 · Oma vuoro — klikkaa sisään, palauta painikkeesta. Suositus.','1 · Your turn — click to take over, return with a button. Recommended.')}</p><p class="${mode===1?'selected':''}">${t('2 · Tauko — kahden minuutin tauko ehdottaa palautusta, ei jatka itsestään.','2 · Pause — two idle minutes suggest returning control, never resume automatically.')}</p><p class="${mode===2?'selected':''}">${t('3 · Pyyntö — agentin seuraava askel näkyy sivussa, sinä hyväksyt.','3 · Request — the next agent step stays alongside the page; you approve.')}</p></div>
    <header class="row spread"><div><h2>${t('Palvelimen selain','Server browser')}</h2><p class="muted">${t('Kirjautuminen · synteettinen esimerkki','Sign-in · synthetic example')}</p></div>${button('lang', 'English', 'Suomi')}</header>
    <div class="${mode===2?'layout-request':''}"><main><div class="ownership row spread"><div><strong>${state.person?t('Sinä ohjaat','You are in control'):t('Agentti ohjaa','Agent is in control')}</strong><small>${state.person?t('Agentin selainkomennot odottavat.','Agent browser commands are paused.'):t('Klikkaa kuvaa tai kirjoita siihen ottaaksesi ohjauksen.','Click or type on the view to take control.')}</small></div>${state.person?button('give','Valmis · anna agentille','Done · return to agent','primary'):''}</div>
    ${mode===1?`<div class="timer"><strong>${t('Sinun rauhassasi','Take your time')}</strong><span>${t('Palautusehdotus 2 min tauon jälkeen','Return suggestion after 2 min idle')}</span></div>`:''}
    <div class="canvas" data-testid="canvas" tabindex="0" role="group" aria-label="${t('Palvelinselaimen kuva','Remote browser view')}"><div class="address">◉ demo.example / sign-in</div><div class="site"><h3>${t('Kirjaudu esimerkkipalveluun','Sign in to the example service')}</h3><label>${t('Käyttäjätunnus','Username')}<input id="remote-field" autocomplete="off" value="${escape(state.value)}" ${!state.person?'disabled':''}></label><label>${t('Salasana (vain mallikuva)','Password (illustration only)')}<input type="password" disabled value="example"></label><button disabled>${t('Kirjaudu','Sign in')}</button></div>${!state.person?`<div class="take-overlay"><strong>${t('Klikkaa ja jatka itse','Click to take over')}</strong><p>${t('Ensimmäinen klikkaus ottaa ohjauksen. Se ei paina sivun painiketta.','The first click takes control. It does not click the page underneath.')}</p>${button('take','Ota ohjaus','Take control')}</div>`:''}</div>
    ${state.warning?`<div class="warning" role="alert"><h3>${t('Agentin toiminto on kesken','An agent action is in progress')}</h3><p>${t('Uudet komennot odottavat. Jo lähetettyä toimintoa ei voi perua: sivu voi vielä muuttua. Odota valmistumista ennen kuin jatkat.','New commands are held. An action already sent cannot be undone: the page may still change. Wait for it to finish before continuing.')}</p><div class="row">${button('finish','Simuloi: toiminto valmistui','Simulate: action finished','primary')}${button('cancel','Peru ohjauspyyntö','Cancel takeover')}</div></div>`:''}
    ${state.idle?`<div class="notice"><strong>${t('Joko olet valmis?','Are you finished?')}</strong><p>${t('Ohjaus on yhä sinulla. Tauko ei ole lupa jatkaa.','You still have control. Inactivity is not permission to resume.')}</p><div class="row">${button('give','Anna agentille','Return to agent')}${button('stay','Jatkan itse','Keep control')}</div></div>`:''}
    <div class="clipboard row spread"><span>${t('Liitä kuvaan: Ctrl / ⌘ + V','Paste into view: Ctrl / ⌘ + V')}</span>${button('tray','Leikepöytä…','Clipboard…')}</div>
    ${state.tray?`<div class="tray"><h3>${t('Teksti koneelta palvelimeen','Text from your computer')}</h3><p>${t('Jos suora liittäminen ei onnistu, liitä tähän. Teksti menee esimerkin käyttäjätunnuskenttään.','If direct paste is blocked, paste here. Text goes to the example username field.')}</p><label for="paste-text">${t('Liitettävä teksti','Text to paste')}</label><textarea id="paste-text" autocomplete="off">${escape(state.draft)}</textarea><div class="row">${button('paste','Liitä sivulle','Paste into page','primary')}${button('type','Kirjoita tekstinä','Type this text')}${button('clear','Tyhjennä','Clear')}</div><small>${t('Kirjoita tekstinä ohittaa etäleikepöydän; se ei paina Enteriä. Tämä ei piilota tekstiä agentilta.','Type this text bypasses the remote clipboard; it does not press Enter. This does not hide text from the agent.')}</small><hr><h3>${t('Palvelimelta omalle koneelle','From server to your computer')}</h3><p>${state.remote?t('Etäsivulta kopioitu teksti on valmis siirrettäväksi.','Copied remote text is ready to transfer.'):t('Kopioi ensin etäsivulla Ctrl / ⌘ + C.','First copy on the remote page with Ctrl / ⌘ + C.')}</p>${state.remote?`<label>${t('Kopioitava teksti','Text to copy')}<textarea id="copy-text" readonly>DEMO-4821</textarea></label>${button('copy','Kopioi omalle koneelle','Copy to your computer')}`:''}</div>`:''}
    <p class="status" role="status">${escape(state.message)}</p><small class="muted">${t('Selain ja kirjautunut istunto ovat agentin käytettävissä. Älä käytä tässä prototyypissä oikeita tunnuksia.','The browser and signed-in session are available to the agent. Do not use real credentials in this prototype.')}</small>
    </main>${mode===2?`<aside><h3>${t('Agentin vuoro','Agent’s turn')}</h3><p>${t('Seuraavaksi: tarkista kirjautuminen.','Next: check sign-in.')}</p><p>${state.request?t('Saanko jatkaa nyt?','May I continue now?'):t('Agentti odottaa sinun lupaasi.','The agent is waiting for your permission.')}</p>${state.request?`<div class="row">${button('give','Saa jatkaa','Allow continuation','primary')}${button('later','Ei vielä','Not yet')}</div>`:''}<small>${t('Vanhaa klikkausta ei toisteta muuttuneelle sivulle.','An old click is not replayed against the changed page.')}</small></aside>`:''}</div>
    <footer class="scenario"><strong>${t('Kokeile tiloja · ei oikeaa etäyhteyttä','Try states · no real remote connection')}</strong><div class="row">${button('busy','Agentti kesken','Agent mid-action')}${button('idle','2 min tauko','2 min idle')}${button('request','Agentti pyytää','Agent requests')}${button('remote','Etäsivulla kopioitu','Remote copy received')}</div></footer></section>`;}
  function render(focus){stage.innerHTML=view();document.querySelector('.page-bar h1').textContent=t('Palvelinselain · ohjaus ja leikepöytä','Server browser · control and clipboard');document.querySelector('#theme').previousSibling.textContent=t('Teema ','Theme ');[...document.querySelector('#theme').options].forEach((o,i)=>o.textContent=(lang==='fi'?['Järjestelmä','Vaalea','Tumma']:['System','Light','Dark'])[i]);document.querySelector('#phone').nextSibling.textContent=t(' Puhelin 390 px',' Phone 390 px');document.querySelectorAll('.proto-picker-item:not(.proto-picker-replay)').forEach((el,i)=>el.textContent=(lang==='fi'?['Oma','Tauko','Pyyntö']:['Yours','Pause','Request'])[i]);window.dispatchEvent(new Event('resize'));if(focus)document.getElementById(focus)?.focus();}
  function take(){if(state.person)return;if(state.busy){state.warning=true;state.message='';render();}else{state.person=true;state.message=t('Ohjaus siirtyi sinulle. Klikkaa nyt kenttää.','Control is yours. Now click the field.');render('remote-field');}}
  stage.addEventListener('input',e=>{if(e.target.id==='remote-field')state.value=e.target.value;if(e.target.id==='paste-text')state.draft=e.target.value;});
  stage.addEventListener('paste',e=>{if(!e.target.closest('.canvas'))return;e.preventDefault();e.stopPropagation();if(!state.person){take();return;}state.value+=e.clipboardData?.getData('text/plain')||'';state.message=t('Teksti liitetty esimerkkikenttään.','Text pasted into the example field.');render('remote-field');});
  // Prevent the shared picker's shortcuts while typing on the remote view.
  stage.addEventListener('keydown',e=>{if(!e.target.closest('.canvas'))return;e.stopPropagation();if(!state.person && e.key!=='Tab' && !['Meta','Control','Alt','Shift'].includes(e.key)){e.preventDefault();take();}});
  stage.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action){if(e.target.closest('.canvas')&&!state.person)take();return;}
    switch(action){
      case 'lang':lang=lang==='fi'?'en':'fi';document.documentElement.lang=lang;break;
      case 'take':take();return;
      case 'busy':state.person=false;state.busy=true;state.warning=false;break;
      case 'finish':state.busy=false;state.warning=false;state.person=true;state.message=t('Toiminto valmistui. Ohjaus on sinulla.','Action completed. You have control.');break;
      case 'cancel':state.warning=false;state.message=t('Ohjauspyyntö peruttu. Agentti jatkaa.','Takeover cancelled. Agent continues.');break;
      case 'give':state.person=false;state.idle=false;state.request=false;state.draft='';state.remote=false;state.message=t('Agentti tarkistaa sivun uudelleen. Vanhoja syötteitä ei toisteta.','Agent rechecks the page. Stale inputs are not replayed.');break;
      case 'stay':state.idle=false;break;
      case 'idle':if(mode===1&&state.person)state.idle=true;else state.message=t('Tässä suunnassa tauko ei muuta ohjausta.','In this direction, inactivity does not change control.');break;
      case 'request':state.request=true;state.message=t('Agentti pyytää jatkaa. Ohjaus ei siirry ilman lupaasi.','Agent asks to continue. Control does not transfer without your approval.');break;
      case 'later':state.request=false;state.message=t('Agentti odottaa.','Agent waits.');break;
      case 'tray':state.tray=!state.tray;break;
      case 'clear':state.draft='';state.remote=false;break;
      case 'paste':case 'type':if(!state.person){state.message=t('Ota ensin ohjaus klikkaamalla kuvaa.','First take control by clicking the view.');break;}state.value+=state.draft;state.draft='';state.message=action==='type'?t('Kirjoitettu ilman Enteriä (simulaatio).','Typed without Enter (simulation).'):t('Liitetty sivulle (simulaatio).','Pasted into page (simulation).');break;
      case 'remote':state.remote=true;state.tray=true;break;
      case 'copy':try{await navigator.clipboard.writeText('DEMO-4821');state.message=t('Kopioitu omalle koneelle.','Copied to your computer.');}catch{state.message=t('Selain esti kopioinnin. Valitse teksti yllä ja kopioi itse.','Browser blocked copying. Select the text above and copy manually.');}break;
    }render();
  });
  window.browserManual=()=>reset(0);window.browserIdle=()=>reset(1);window.browserRequest=()=>reset(2);
})();
